code.cpp:
class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        int n = nums.size();
        int target = n - k;                     // index in sorted order (0‑based)

        srand(static_cast<unsigned>(time(nullptr)));

        function<int(int,int)> quickSelect = [&](int left, int right) -> int {
            while (true) {
                if (left == right) return nums[left];

                // random pivot
                int pivotIdx = left + rand() % (right - left + 1);
                int pivotVal = nums[pivotIdx];
                swap(nums[pivotIdx], nums[right]);   // move pivot to end

                // partition: elements <= pivot to the left
                int storeIdx = left;
                for (int i = left; i < right; ++i) {
                    if (nums[i] <= pivotVal) {
                        swap(nums[storeIdx], nums[i]);
                        ++storeIdx;
                    }
                }
                swap(nums[storeIdx], nums[right]);   // pivot to its final place

                if (storeIdx == target) return nums[storeIdx];
                else if (storeIdx > target) {
                    right = storeIdx - 1;
                } else {
                    left = storeIdx + 1;
                }
            }
        };

        return quickSelect(0, n - 1);
    }
};
